     7→use proto_array::Block as ProtoBlock;
     8→use std::sync::Arc;
     9→use types::*;
    10→
    11→pub struct CacheItem<E: EthSpec> {
    12→    /*
    13→     * Values used to create attestations.
    14→     */
    15→    epoch: Epoch,
    16→    committee_lengths: CommitteeLengths,
    17→    beacon_block_root: Hash256,
    18→    source: Checkpoint,
    19→    target: Checkpoint,
    20→    /*
    21→     * Values used to make the block available.
    22→     */
    23→    block: Arc<SignedBeaconBlock<E>>,
    24→    blobs: Option<BlobSidecarList<E>>,
    25→    data_columns: Option<DataColumnSidecarList<E>>,
    26→    proto_block: ProtoBlock,
    27→}
    28→
    29→/// Provides a single-item cache which allows for attesting to blocks before those blocks have
    30→/// reached the database.
    31→///
    32→/// This cache stores enough information to allow Lighthouse to:
    33→///
    34→/// - Produce an attestation without using `chain.canonical_head`.
    35→/// - Verify that a block root exists (i.e., will be imported in the future) during attestation
    36→///   verification.
    37→/// - Provide a block which can be sent to peers via RPC.
    38→#[derive(Default)]
    39→pub struct EarlyAttesterCache<E: EthSpec> {
    40→    item: RwLock<Option<CacheItem<E>>>,
    41→}
    42→
    43→impl<E: EthSpec> EarlyAttesterCache<E> {
    44→    /// Removes the cached item, meaning that all future calls to `Self::try_attest` will return
    45→    /// `None` until a new cache item is added.
    46→    pub fn clear(&self) {
    47→        *self.item.write() = None
    48→    }
    49→
    50→    /// Updates the cache item, so that `Self::try_attest` with return `Some` when given suitable
    51→    /// parameters.
    52→    pub fn add_head_block(
    53→        &self,
    54→        beacon_block_root: Hash256,
    55→        block: &AvailableBlock<E>,
    56→        proto_block: ProtoBlock,
    57→        state: &BeaconState<E>,
    58→        spec: &ChainSpec,
    59→    ) -> Result<(), Error> {
    60→        let epoch = state.current_epoch();
    61→        let committee_lengths = CommitteeLengths::new(state, spec)?;
    62→        let source = state.current_justified_checkpoint();
    63→        let target_slot = epoch.start_slot(E::slots_per_epoch());
    64→        let target = Checkpoint {
    65→            epoch,
    66→            root: if state.slot() <= target_slot {
    67→                beacon_block_root
    68→            } else {
    69→                *state.get_block_root(target_slot)?
    70→            },
    71→        };
    72→
    73→        let (blobs, data_columns) = match block.data() {
    74→            AvailableBlockData::NoData => (None, None),
    75→            AvailableBlockData::Blobs(blobs) => (Some(blobs.clone()), None),
    76→            AvailableBlockData::DataColumns(data_columns) => (None, Some(data_columns.clone())),
    77→        };
    78→
    79→        let item = CacheItem {
    80→            epoch,
    81→            committee_lengths,
    82→            beacon_block_root,
    83→            source,
    84→            target,
    85→            block: block.block_cloned(),
    86→            blobs,
    87→            data_columns,
    88→            proto_block,
    89→        };
    90→
    91→        *self.item.write() = Some(item);
    92→
    93→        Ok(())
    94→    }
    95→
    96→    /// Will return `Some(attestation)` if all the following conditions are met:
    97→    ///
    98→    /// - There is a cache `item` present.
    99→    /// - If `request_slot` is in the same epoch as `item.epoch`.
   100→    /// - If `request_index` does not exceed `item.committee_count`.
   101→    pub fn try_attest(
   102→        &self,
   103→        request_slot: Slot,
   104→        request_index: CommitteeIndex,
   105→        spec: &ChainSpec,
   106→    ) -> Result<Option<Attestation<E>>, Error> {
   107→        let lock = self.item.read();
   108→        let Some(item) = lock.as_ref() else {
   109→            return Ok(None);
   110→        };
   111→
   112→        let request_epoch = request_slot.epoch(E::slots_per_epoch());
   113→        if request_epoch != item.epoch {
   114→            return Ok(None);
   115→        }
   116→
   117→        if request_slot < item.block.slot() {
   118→            return Ok(None);
   119→        }
   120→
   121→        let committee_count = item
   122→            .committee_lengths
   123→            .get_committee_count_per_slot::<E>(spec)?;
   124→        if request_index >= committee_count as u64 {
   125→            return Ok(None);
   126→        }
   127→
   128→        let committee_len =
   129→            item.committee_lengths
   130→                .get_committee_length::<E>(request_slot, request_index, spec)?;
   131→
   132→        let attestation = Attestation::empty_for_signing(
   133→            request_index,
   134→            committee_len,
   135→            request_slot,
   136→            item.beacon_block_root,
   137→            item.source,
   138→            item.target,
   139→            spec,
   140→        )
   141→        .map_err(Error::AttestationError)?;
   142→
   143→        metrics::inc_counter(&metrics::BEACON_EARLY_ATTESTER_CACHE_HITS);
   144→
   145→        Ok(Some(attestation))
   146→    }
   147→
   148→    /// Returns `true` if `block_root` matches the cached item.
   149→    pub fn contains_block(&self, block_root: Hash256) -> bool {
   150→        self.item
   151→            .read()
   152→            .as_ref()
   153→            .is_some_and(|item| item.beacon_block_root == block_root)
   154→    }
   155→
   156→    /// Returns the block, if `block_root` matches the cached item.
   157→    pub fn get_block(&self, block_root: Hash256) -> Option<Arc<SignedBeaconBlock<E>>> {
   158→        self.item
   159→            .read()
   160→            .as_ref()
   161→            .filter(|item| item.beacon_block_root == block_root)
   162→            .map(|item| item.block.clone())
   163→    }
   164→
   165→    /// Returns the blobs, if `block_root` matches the cached item.
   166→    pub fn get_blobs(&self, block_root: Hash256) -> Option<BlobSidecarList<E>> {
   167→        self.item
   168→            .read()
   169→            .as_ref()
   170→            .filter(|item| item.beacon_block_root == block_root)
   171→            .and_then(|item| item.blobs.clone())
   172→    }
   173→
   174→    /// Returns the data columns, if `block_root` matches the cached item.
   175→    pub fn get_data_columns(&self, block_root: Hash256) -> Option<DataColumnSidecarList<E>> {
   176→        self.item
   177→            .read()
   178→            .as_ref()
   179→            .filter(|item| item.beacon_block_root == block_root)
   180→            .and_then(|item| item.data_columns.clone())
   181→    }
   182→
   183→    /// Returns the proto-array block, if `block_root` matches the cached item.
   184→    pub fn get_proto_block(&self, block_root: Hash256) -> Option<ProtoBlock> {
